        sku_version: 1,
        version: "2",
        line_id: o.line.id,
        quantity: "40",
      })
    ).json();
    const b = (
      await f.command("outbounds/" + o.id + "/shipments", {
        ...f.evidence(),
        sku_id: f.sku.id,
        sku_version: 1,
        version: "3",
        line_id: o.line.id,
        quantity: "55",
      })
    ).json();
    const receipt = {
      ...f.evidence(),
      sku_id: f.sku.id,
      sku_version: 1,
      version: "1",
      shipment_line_id: a.shipment_line_id,
      quantity: "39",
