  await expect(
    f.db.pool.query(
      "UPDATE inventory_balances SET quantity=quantity+1 WHERE account_id=$1",
      [e.account_id],
    ),
  ).rejects.toThrow("PROJECTION");
  await expect(
    f.db.pool.query(
      "UPDATE inventory_balances SET reserved=1000 WHERE account_id=$1",
      [e.account_id],
    ),
