    await c.query(
      "INSERT INTO inventory_entries(id,transaction_id,sku_id,account_id,quantity,line_no,recorded_at) SELECT $1,$2,$3,$4,1,1,recorded_at FROM inventory_transactions WHERE id=$2",
      [randomUUID(), id, e.sku_id, e.account_id],
